import numpy as np,time
from numba import njit
from scipy.optimize import linear_sum_assignment
@njit(cache=True,fastmath=True)
def auc(c):
 n=c.shape[0];p=np.zeros(n);own=np.full(n,-1,np.int32);ass=np.full(n,-1,np.int32);eps=.05
 while eps>1e-10:
  own[:]=-1;ass[:]=-1;st=np.arange(n,dtype=np.int32);top=n
  while top:
   top-=1;i=st[top]; vals=c[i]+p; bj=np.argmin(vals); be=vals[bj]; vals[bj]=1e100;se=np.min(vals); vals[bj]=be
   p[bj]+=se-be+eps;o=own[bj];own[bj]=i;ass[i]=bj
   if o>=0:ass[o]=-1;st[top]=o;top+=1
  eps*=.2
 return ass
