{"command":"cat > hungarian.py <<'PY'
import numpy as np,time
from numba import njit
from scipy.optimize import linear_sum_assignment
@njit(cache=True,fastmath=True)
def hung(a):
 n=a.shape[0];u=np.zeros(n+1);v=np.zeros(n+1);p=np.zeros(n+1,np.int32);way=np.zeros(n+1,np.int32)
 for i in range(1,n+1):
  p[0]=i;j0=0;mv=np.full(n+1,1e100);used=np.zeros(n+1,np.uint8)
  while True:
   used[j0]=1;i0=p[j0];delta=1e100;j1=0
   for j in range(1,n+1):
    if used[j]==0:
     cur=a[i0-1,j-1]-u[i0]-v[j]
     if cur<mv[j]:mv[j]=cur;way[j]=j0
     if mv[j]<delta:delta=mv[j];j1=j
   for j in range(n+1):
    if used[j]:u[p[j]]+=delta;v[j]-=delta
    else:mv[j]-=delta
   j0=j1
   if p[j0]==0:break
  while True:
   j1=way[j0];p[j0]=p[j1];j0=j1
   if j0==0:break
 ans=np.empty(n,np.int32)
 for j in range(1,n+1):ans[p[j]-1]=j-1
 return ans
hung(np.random.rand(10,10))
for s in range(20):
 np.random.seed(s);x=np.random.rand(600,2);y=np.random.rand(600,2);c=np.linalg.norm(x[:,None]-y,axis=2);r,z=linear_sum_assignment(c);t=time.perf_counter();q=hung(c);print((time.perf_counter()-t)*1000,np.array_equal(q,z))
